#!/usr/bin/env python3
"""Build data/news.js from:
  1) itch.io devlog RSS feeds listed in config.js (SITE.news.feeds)
  2) Patreon posts (titles only) via the official Patreon API,
     if the GitHub secret PATREON_TOKEN is set.
Runs in GitHub Actions; standard library only."""
import html
import json
import os
import re
import sys
import urllib.parse
import urllib.request
import xml.etree.ElementTree as ET
from email.utils import parsedate_to_datetime
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
CONFIG = ROOT / "config.js"
OUT = ROOT / "data" / "news.js"
MAX_PER_FEED = 15
UA = {"User-Agent": "Mozilla/5.0 (HaruGameStudio news bot)"}

feeds = re.findall(r'\{\s*project:\s*"([^"]+)"\s*,\s*url:\s*"([^"]+)"\s*\}', CONFIG.read_text(encoding="utf-8"))


def clean(text, limit=200):
    text = html.unescape(re.sub(r"<[^>]+>", " ", text or ""))
    text = re.sub(r"\s+", " ", text).strip()
    return text if len(text) <= limit else text[:limit].rsplit(" ", 1)[0] + "…"


def get(url, headers=None):
    req = urllib.request.Request(url, headers={**UA, **(headers or {})})
    return urllib.request.urlopen(req, timeout=30).read()


items, sources_ok, sources_total = [], 0, 0

# ---------- 1) itch.io devlogs ----------
for project, url in feeds:
    sources_total += 1
    try:
        root = ET.fromstring(get(url))
    except Exception as e:  # keep going if one feed fails
        print(f"[warn] {project}: {e}")
        continue
    for it in list(root.iter("item"))[:MAX_PER_FEED]:
        try:
            date = parsedate_to_datetime(it.findtext("pubDate")).isoformat()
        except Exception:
            date = it.findtext("pubDate") or ""
        items.append({
            "source": "itch",
            "project": project,
            "title": (it.findtext("title") or "").strip(),
            "link": (it.findtext("link") or "").strip(),
            "date": date,
            "summary": clean(it.findtext("description")),
        })
    sources_ok += 1
    print(f"[ok] itch.io: {project}")

# ---------- 2) Patreon (titles only) ----------
token = os.environ.get("PATREON_TOKEN", "").strip()
if token:
    sources_total += 1
    try:
        auth = {"Authorization": f"Bearer {token}"}
        ident = json.loads(get("https://www.patreon.com/api/oauth2/v2/identity?include=campaign", auth))
        campaigns = ident.get("data", {}).get("relationships", {}).get("campaign", {}).get("data")
        if not campaigns:
            raise RuntimeError("no campaign found for this token")
        cid = campaigns["id"]
        url = (f"https://www.patreon.com/api/oauth2/v2/campaigns/{cid}/posts?"
               + urllib.parse.urlencode({"fields[post]": "title,published_at,url", "page[count]": 100}))
        posts, pages = [], 0
        while url and pages < 10:
            page = json.loads(get(url, auth))
            posts += page.get("data", [])
            url = page.get("links", {}).get("next")
            pages += 1
        posts = [p["attributes"] for p in posts if p.get("attributes", {}).get("published_at")]
        posts.sort(key=lambda a: a["published_at"], reverse=True)
        for a in posts[:MAX_PER_FEED]:
            link = a.get("url") or ""
            if link.startswith("/"):
                link = "https://www.patreon.com" + link
            items.append({
                "source": "patreon",
                "project": "Patreon",
                "title": (a.get("title") or "Patreon post").strip(),
                "link": link or "https://www.patreon.com/ruslanharu",
                "date": a["published_at"],
                "summary": "",
            })
        sources_ok += 1
        print(f"[ok] Patreon: {len(posts)} posts")
    except Exception as e:
        print(f"[warn] Patreon: {e}")
else:
    print("[skip] Patreon: no PATREON_TOKEN secret")

if not sources_total:
    sys.exit("No sources configured")
if not sources_ok:
    sys.exit("All sources failed — keeping old news.js")

items.sort(key=lambda x: x["date"], reverse=True)
OUT.parent.mkdir(exist_ok=True)
OUT.write_text("/* Auto-generated by .github/scripts/fetch_news.py — do not edit by hand */\nconst NEWS = "
               + json.dumps({"items": items}, ensure_ascii=False, indent=1) + ";\n", encoding="utf-8")
print(f"Wrote {len(items)} items to {OUT.relative_to(ROOT)}")
